const makeRepo = ({ name, url, stars, description, language, tags, category }) => ({
  name,
  url,
  stars,
  description: description || `${name} open-source project`,
  category,
  features: [language, ...(tags || '').split('|').filter(Boolean)].filter(Boolean).slice(0, 6),
  install: `git clone ${url}`,
  useCase: description || `Explore the ${name} project`,
})

